import{_ as s,o as a,c as t,ak as i}from"./chunks/framework.BXerppJ0.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"contributing/index.md","filePath":"contributing/index.md","lastUpdated":1794593038000}'),n={name:"contributing/index.md"};function r(l,e,o,p,d,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Thanks for helping improve RPG Dice Roller! Bug reports, ideas, documentation fixes and code contributions are all welcome.</p><p>Please follow our <a href="./code-of-conduct.html">Code of Conduct</a> when participating.</p><h2 id="questions-bugs-and-ideas" tabindex="-1">Questions, bugs and ideas <a class="header-anchor" href="#questions-bugs-and-ideas" aria-label="Permalink to &quot;Questions, bugs and ideas&quot;">​</a></h2><p>Use <a href="https://github.com/dice-roller/rpg-dice-roller/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> for questions and general discussion.</p><p>For bugs and feature suggestions, <a href="https://github.com/dice-roller/rpg-dice-roller/issues/new/choose" target="_blank" rel="noreferrer">open an issue</a>. Please search existing issues first and add to an existing discussion where appropriate.</p><p>For a bug report, include:</p><ul><li>The library version and environment you’re using.</li><li>A small code example or dice notation that reproduces the problem.</li><li>What you expected to happen and what actually happened.</li><li>Any relevant error messages.</li></ul><p>For a feature suggestion, explain the use case and give an example of how you’d like it to work.</p><h2 id="choosing-something-to-work-on" tabindex="-1">Choosing something to work on <a class="header-anchor" href="#choosing-something-to-work-on" aria-label="Permalink to &quot;Choosing something to work on&quot;">​</a></h2><p>Browse the <a href="https://github.com/dice-roller/rpg-dice-roller/issues" target="_blank" rel="noreferrer">open issues</a>, particularly those labelled <a href="https://github.com/dice-roller/rpg-dice-roller/issues?q=is%3Aissue+is%3Aopen+label%3A%22help+wanted%22,%22good+first+issue%22" target="_blank" rel="noreferrer">good first issue or help wanted</a>.</p><p>If you’d like to work on an issue, leave a comment so others know. For larger changes or new features, discuss the approach before spending too much time on the implementation.</p><p>Small fixes, including typo corrections and clearer examples, are welcome too.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><h3 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h3><p>You’ll need Node.js and npm. Use the latest Node.js LTS release, which is also used by the project’s CI checks.</p><p>Fork the <a href="https://github.com/dice-roller/rpg-dice-roller" target="_blank" rel="noreferrer">library repository</a> and create a branch for your changes.</p><p>Choose the base branch that matches your contribution:</p><ul><li><code>develop</code> — fixes and improvements for the current released major version.</li><li><code>next</code> — development of the next major version.</li></ul><p>Open your pull request against the branch you started from. If you’re unsure which branch to use, ask in the related issue or discussion.</p><p>Install dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre></div><p>Then run the checks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>This generates the parser, checks TypeScript types, runs linting and formatting checks, and then runs the Jest tests. You do not need to build the library bundles first.</p><h3 id="finding-your-way-around" tabindex="-1">Finding your way around <a class="header-anchor" href="#finding-your-way-around" aria-label="Permalink to &quot;Finding your way around&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>src/</code></td><td>TypeScript source code and the public entry point, <code>src/index.ts</code>.</td></tr><tr><td><code>src/ast/</code></td><td>The parsed notation structure and helpers for working with it.</td></tr><tr><td><code>src/parser/</code></td><td>The notation parser and Peggy grammar.</td></tr><tr><td><code>src/dice/</code></td><td>Dice definitions and their registry.</td></tr><tr><td><code>src/modifiers/</code></td><td>Modifier implementations and their registry.</td></tr><tr><td><code>src/evaluator/</code></td><td>Evaluates parsed notation and applies dice and modifiers.</td></tr><tr><td><code>src/results/</code></td><td>Result types, flags and helpers.</td></tr><tr><td><code>src/presenters/</code></td><td>Formats evaluated results for display.</td></tr><tr><td><code>src/random/</code></td><td>Random number generation.</td></tr><tr><td><code>src/serialization/</code></td><td>Roll import and export.</td></tr><tr><td><code>tests/</code></td><td>Automated tests.</td></tr><tr><td><code>dist/</code></td><td>Generated ESM and UMD bundles and TypeScript declarations.</td></tr><tr><td><code>docs/api/</code></td><td>Generated API documentation.</td></tr></tbody></table><p>Make changes in the source files rather than editing generated bundles, parser files or API documentation.</p><h3 id="code-style" tabindex="-1">Code style <a class="header-anchor" href="#code-style" aria-label="Permalink to &quot;Code style&quot;">​</a></h3><p>The project uses ESLint for code checks and Prettier for formatting. Follow the existing code and let these tools handle the formatting details.</p><p>Check your changes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span></code></pre></div><p>Apply automatic fixes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint:fix</span></span></code></pre></div><p>You can also run formatting separately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span></span></code></pre></div><p>TypeScript type checking is available independently:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>On a fresh checkout, generate the parser before running type checking directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:grammars</span></span></code></pre></div><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><p>Tests use Jest and are written in TypeScript under <code>tests/</code>.</p><p>Add or update tests when changing behaviour. For a bug fix, include a test that reproduces the problem and verifies the fix.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run all checks and tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run a particular test file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/parser/dice.test.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run tests in watch mode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:watch</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate a coverage report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:coverage</span></span></code></pre></div><p>Use descriptive test names and examples that make the expected behaviour clear.</p><p>The files under <code>tests/v5/</code> are retained as reference material and are excluded from the active test suite.</p><h3 id="changing-the-notation-grammar" tabindex="-1">Changing the notation grammar <a class="header-anchor" href="#changing-the-notation-grammar" aria-label="Permalink to &quot;Changing the notation grammar&quot;">​</a></h3><p>The notation parser is generated using <a href="https://github.com/peggyjs/peggy" target="_blank" rel="noreferrer">Peggy</a>. Its grammar lives in <code>src/parser/grammar.pegjs</code>.</p><p>If you’re unfamiliar with the syntax, start with the <a href="https://peggyjs.org/documentation.html" target="_blank" rel="noreferrer">Peggy documentation</a>. The <a href="https://github.com/peggyjs/peggy/wiki/Editor-Extensions" target="_blank" rel="noreferrer">editor extensions wiki</a> lists syntax-highlighting plugins for various editors and IDEs.</p><p>After editing the grammar, regenerate the parser:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:grammars</span></span></code></pre></div><p>This writes the generated parser and its declarations into <code>src/parser/generated/</code>. Do not edit those generated files directly.</p><p>Add parser tests for new or changed syntax, along with evaluation tests where the change affects how rolls behave.</p><p>The normal test and build commands regenerate the parser automatically. If you edit the grammar during a watch session, run the grammar command again.</p><h3 id="building-the-library" tabindex="-1">Building the library <a class="header-anchor" href="#building-the-library" aria-label="Permalink to &quot;Building the library&quot;">​</a></h3><p>Rollup builds the library into ESM and UMD bundles.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build development and minified production bundles, plus type declarations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build unminified ESM and UMD bundles</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:dev</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build minified ESM and UMD bundles</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:prod</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build TypeScript declarations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:definitions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Watch for source changes and rebuild development bundles</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span></span></code></pre></div><p>Generated files are written to <code>dist/</code>.</p><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>The website guides are maintained in the separate <a href="https://github.com/dice-roller/documentation" target="_blank" rel="noreferrer">documentation repository</a>.</p><p>The library’s API reference is generated from its TypeScript source and documentation comments:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate the API reference</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Regenerate it as source files change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:watch</span></span></code></pre></div><p>The generated reference is written to <code>docs/api/</code>. Update the source comments rather than editing the generated Markdown.</p><h2 id="pull-requests" tabindex="-1">Pull requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull requests&quot;">​</a></h2><p>Keep each pull request focused on one change where practical.</p><p>Include a short explanation of:</p><ul><li>What changed and why.</li><li>Any related issues.</li><li>How you checked the change.</li></ul><p>Before submitting, run <code>npm test</code>. If your changes affect the build, public types or API documentation, also run the relevant build commands.</p><p>Use short, descriptive commit messages such as “Fix exploding dice comparison”.</p><p>After opening the pull request, check the CI results. If a check fails and you believe it is unrelated to your changes, explain that in the pull request.</p><h2 id="use-of-ai" tabindex="-1">Use of AI <a class="header-anchor" href="#use-of-ai" aria-label="Permalink to &quot;Use of AI&quot;">​</a></h2><p>You’re welcome to use AI tools to help write code, improve documentation, or draft issues and comments. The same contribution guidelines apply whether or not you use AI.</p><p>Please review and verify anything you submit. If you’re reporting a bug, check that you can reproduce it. If you’re opening a pull request, make sure you understand the changes, can explain why they’re needed, and have run the relevant tests. Be prepared to answer questions about your contribution.</p><p>Maintainers may close or remove spam, irrelevant submissions, or bulk-generated content posted without meaningful review. Accounts that repeatedly post this material or engage in deliberate abuse may be blocked from participating in the project.</p>`,74)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
